// Verify Webhook — Meta's one-time check when the webhook URL is saved in the app settings.
const cfg = $('Config').first().json;
const query = $('Verify Webhook').first().json.query || {};
const ok = query['hub.mode'] === 'subscribe' && cfg.verify_token && !String(cfg.verify_token).startsWith('REPLACE') && query['hub.verify_token'] === cfg.verify_token;
return [{ json: { ok, status: ok ? 200 : 403, body: ok ? String(query['hub.challenge'] || '') : 'forbidden' } }];

