const sent = Number(m.timestamp) * 1000;
// Meta retries undelivered webhooks; a message older than the window has already been answered or lost its moment.
if (sent && now - sent > (cfg.max_message_age_minutes || 60) * MIN) return skip('stale', { wa_id: m.from });
return [{ json: {
