    }
    if (STAGES.includes(p.stage)) contact.stage = p.stage;
    buttons = Array.isArray(p.buttons) ? p.buttons.map((b) => String(b).trim().slice(0, 20)).filter(Boolean).slice(0, 3) : [];
    summary = String(p.summary || '').slice(0, 300);
    const hot = p.hot === true || contact.stage === 'hot';
    if (hot && contact.hot !== 'yes') { contact.hot = 'yes'; route = 'hot'; reason = 'клиент готов к следующему шагу'; }
    else if (p.handoff === true) { route = 'handoff'; reason = String(p.handoff_reason || 'нужен человек').slice(0, 200); }
  } else {
    // Without a model answer the client is not left in silence: a person takes over.
    route = 'handoff'; reason = 'модель не ответила'; reply = cfg.texts.fallback; problem = problem || 'empty';
  }
}
if (route === 'handoff' || route === 'hot') {
  contact.status = 'manager';
  contact.handoff_until = new Date(now + (cfg.handoff_hours || 12) * 60 * MIN).toISOString();
  if (route === 'handoff' && !reply) reply = cfg.texts.handoff;
}
if (reply) {
  contact.last_out_at = iso;
  contact.history = `${contact.history}\n${localText(now)} · бот: ${reply.replace(/\n+/g, ' ').slice(0, 400)}`.slice(-3500);
}
const message = !reply ? null : buttons.length && route === 'ai'
  ? { messaging_product: 'whatsapp', recipient_type: 'individual', to: msg.wa_id, type: 'interactive',
      interactive: { type: 'button', body: { text: reply.slice(0, 1024) }, action: { buttons: buttons.map((title, i) => ({ type: 'reply', reply: { id: `b${i + 1}`, title } })) } } }
  : waText(msg.wa_id, reply);

const values = [CCOLS.map((c) => String(contact[c] || ''))];
const http = ctx.sheet_row
  ? { method: 'PUT', url: sheetUrl(encodeURIComponent(contactRow(ctx.sheet_row))) + '?valueInputOption=RAW', body: { values } }
  : { method: 'POST', url: sheetUrl(encodeURIComponent(contactsRange()) + ':append') + '?valueInputOption=RAW&insertDataOption=INSERT_ROWS', body: { values: ctx.has_header ? values : [CCOLS, ...values] } };

const known = (cfg.qualify || []).filter((q) => contact[q.key]).map((q) => `${q.label}: ${contact[q.key]}`);
let team = '';
if (route === 'hot' || route === 'handoff' || route === 'to_manager') {
  team = [
    route === 'hot' ? 'Горячий клиент в WhatsApp' : route === 'to_manager' ? 'Новое сообщение клиента (разговор у менеджера)' : 'Нужен менеджер в WhatsApp',
    `Клиент: ${contact.name || 'без имени'}, +${msg.wa_id}`,
    reason && route !== 'to_manager' ? `Причина: ${reason}` : '',
    `Сообщение: ${msg.text.slice(0, 800)}`,
    summary ? `Кратко: ${summary}` : '',
    ...known,
    route !== 'to_manager' ? `Последнее в переписке:\n${contact.history.split('\n').slice(-6).join('\n')}` : '',
    'Ответить: ответом на это сообщение — текст уйдёт клиенту в WhatsApp.',
    `WA: ${msg.wa_id}`,
  ].filter(Boolean).join('\n');
}
return [{ json: {
  route, wa_id: msg.wa_id, problem,
  client: { name: contact.name || '', phone: '+' + msg.wa_id, stage: contact.stage || '', need: contact.need || '', budget: contact.budget || '', timeline: contact.timeline || '' },
  send: Boolean(message) && route !== 'silent' && route !== 'to_manager', message, graph_url: graphUrl(),
  http, notify: Boolean(team), team_chat: cfg.team_chat_id, team_text: team, buttons_for_team: route === 'hot' || route === 'handoff',
} }];

// Not Delivered — WhatsApp refused the message (most often: more than 24 hours since the client wrote). A person must act.
const sent = $('Reply').first().json;
const error = $input.first().json.error || $input.first().json;
const raw = JSON.stringify(error);
const window = /131047|re-engagement/i.test(raw);
return [{ json: { text: [
  'Сообщение в WhatsApp не доставлено',
  `Клиент: +${sent.wa_id || (sent.message || {}).to || '—'}`,
  window ? 'Причина: прошло больше 24 часов с последнего сообщения клиента — WhatsApp разрешает только одобренный шаблон.' : `Ошибка: ${raw.slice(0, 300)}`,
  `Текст: ${(((sent.message || {}).text || {}).body || ((((sent.message || {}).interactive || {}).body) || {}).text || '').slice(0, 600)}`,
].join('\n') } }];

// Sheet Unavailable — the bot cannot see the client's history, so it does not answer blind. The team gets the message.
let msg = {};
try { msg = $('Inbound').first().json; } catch (e) {}
const error = $input.first().json.error || $input.first().json;
return [{ json: { text: ['Таблица недоступна — бот не ответил, ответьте вручную', `Клиент: ${msg.name || ''} +${msg.wa_id || '—'}`, `Сообщение: ${(msg.text || '').slice(0, 1200)}`,
  `Ошибка: ${JSON.stringify(error).slice(0, 300)}`, `WA: ${msg.wa_id || ''}`].join('\n') } }];
